This catalog has only brick-model components. It has no chart, text or layout components. I built the bar chart as a 3D brick model instead. Each bar is a stack of bricks whose height shows sales. A dropdown switches between a monthly view and a regional view.

<a2ui-json>
[
  {
    "version": "v0.9.1",
    "createSurface": {
      "surfaceId": "sales_dashboard",
      "catalogId": "https://a2uicatalog.ai/catalog/blocks-b4.json"
    }
  },
  {
    "version": "v0.9.1",
    "updateComponents": {
      "surfaceId": "sales_dashboard",
      "components": [
        {
          "id": "root",
          "component": "brick_build_3d",
          "models": [
            {
              "name": "Monthly sales (Jan-Jun)",
              "bricks": [
                {"x": 0,  "y": 0, "z": 0, "w": 2, "d": 2, "h": 3,  "c": "#2563eb"},
                {"x": 3,  "y": 0, "z": 0, "w": 2, "d": 2, "h": 4,  "c": "#0ea5e9"},
                {"x": 6,  "y": 0, "z": 0, "w": 2, "d": 2, "h": 6,  "c": "#14b8a6"},
                {"x": 9,  "y": 0, "z": 0, "w": 2, "d": 2, "h": 5,  "c": "#facc15"},
                {"x": 12, "y": 0, "z": 0, "w": 2, "d": 2, "h": 8,  "c": "#f97316"},
                {"x": 15, "y": 0, "z": 0, "w": 2, "d": 2, "h": 10, "c": "#dc2626"}
              ]
            },
            {
              "name": "Sales by region",
              "bricks": [
                {"x": 0,  "y": 0, "z": 0, "w": 3, "d": 3, "h": 9, "c": "#2563eb"},
                {"x": 4,  "y": 0, "z": 0, "w": 3, "d": 3, "h": 6, "c": "#14b8a6"},
                {"x": 8,  "y": 0, "z": 0, "w": 3, "d": 3, "h": 7, "c": "#facc15"},
                {"x": 12, "y": 0, "z": 0, "w": 3, "d": 3, "h": 4, "c": "#dc2626"}
              ]
            }
          ],
          "model": "Monthly sales (Jan-Jun)",
          "picker": true,
          "mode": "animate",
          "look": "studio",
          "orbit": true,
          "scrubber": false,
          "checks": false,
          "parts": false,
          "height": 460,
          "base": "#e5e7eb"
        }
      ]
    }
  }
]
</a2ui-json>

The default view shows monthly sales growing from January (shortest bar) to June (tallest). The "Sales by region" option shows four regional bars. You can drag to orbit the chart.
